from datetime import datetime
from typing import Dict, NamedTuple


class Appointment(NamedTuple):
    id: int
    patient: str
    doctor: str
    start: datetime
    end: datetime


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, Appointment] = {}

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Appointment start time must be strictly before end time.")

        # Requirement 4: Booking an appointment that starts before `now` raises ValueError.
        if start < now:
            raise ValueError("Cannot book an appointment that starts in the past.")

        # Requirement 2: A patient can have at most one upcoming appointment.
        # An upcoming appointment is one that has not yet finished relative to `now`.
        for appt in self._appointments.values():
            if appt.patient == patient and appt.end > now:
                raise ValueError(
                    f"Patient '{patient}' already has an upcoming appointment."
                )

        # Requirement 3: Overlapping another appointment of the same doctor raises ValueError.
        if not self.is_free(doctor, start, end):
            raise ValueError(
                f"Doctor '{doctor}' is not available during the requested time slot."
            )

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = Appointment(
            id=appointment_id,
            patient=patient,
            doctor=doctor,
            start=start,
            end=end,
        )
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an existing appointment."""
        if appointment_id not in self._appointments:
            raise ValueError(f"Appointment ID {appointment_id} does not exist.")

        appt = self._appointments[appointment_id]
        if appt.end <= now:
            raise ValueError("Cannot cancel an appointment that has already finished.")

        del self._appointments[appointment_id]

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            raise ValueError("Start time must be strictly before end time.")

        # Requirement 1: Appointments that only touch do not overlap.
        # Two intervals [start, end) and [s, e) overlap if max(start, s) < min(end, e).
        for appt in self._appointments.values():
            if appt.doctor == doctor:
                if max(start, appt.start) < min(end, appt.end):
                    return False
        return True
```

